# Generated by test-lab — blind adversarial evaluation
"""API integration for split interviewer question windowing."""

import json
from pathlib import Path
import time

import os
os.environ.setdefault("LIVE_EVIDENCE_SCANNER_MODE", "false")  # legacy window-path tests


from fastapi.testclient import TestClient

from live_evidence.api import create_app
from live_evidence.config import AppSettings


def make_settings(tmp_path: Path) -> AppSettings:
    profile_path = tmp_path / "profile.yaml"
    profile_path.write_text(
        "name: question-window-api-test\n"
        "watch_terms:\n"
        "  - invalid parentheses\n"
        "project_aliases: {}\n",
        encoding="utf-8",
    )
    return AppSettings(
        skill_root=tmp_path,
        data_dir=tmp_path / "data",
        profile_path=profile_path,
        repo_roots=[],
        memory_url="http://127.0.0.1:9",
        request_timeout_s=0.2,
        subprocess_timeout_s=0.5,
    )


def post_turn(
    client: TestClient,
    sequence: int,
    text: str,
    speaker: str = "interviewer",
    kind: str = "final",
) -> None:
    response = client.post(
        "/api/transcript",
        json={
            "schema": "live_evidence.transcript_event.v1",
            "speaker": speaker,
            "kind": kind,
            "source": "api",
            "sequence": sequence,
            "text": text,
        },
    )
    assert response.status_code == 202


def read_journal(data_dir: Path) -> list[dict]:
    paths = list(data_dir.glob("*/session.jsonl"))
    if not paths:
        return []
    return [json.loads(line) for line in paths[0].read_text(encoding="utf-8").splitlines()]


def wait_for_publication_decisions(data_dir: Path, count: int) -> list[dict]:
    deadline = time.monotonic() + 3.0
    while time.monotonic() < deadline:
        decisions = [
            row for row in read_journal(data_dir)
            if row.get("kind") == "card_publication_decision"
        ]
        if len(decisions) >= count:
            return decisions
        time.sleep(0.05)
    raise AssertionError(f"timed out waiting for {count} publication decision(s)")


def test_split_interviewer_question_creates_one_joined_card(tmp_path: Path) -> None:
    app = create_app(make_settings(tmp_path))
    with TestClient(app) as client:
        client.post("/api/session/start", json={"consent_confirmed": True}).raise_for_status()

        post_turn(client, 1, "Given a string with parentheses, how would")
        time.sleep(0.2)
        assert client.get("/api/state").json()["cards"] == []

        post_turn(client, 2, "you remove the minimum invalid parentheses?")
        decisions = wait_for_publication_decisions(tmp_path / "data", 1)
        payload = client.get("/api/state").json()

    assert payload["cards"] == []
    decision = decisions[-1]["payload"]
    assert decision["status"] == "held"
    assert decision["reason_codes"] == ["insufficient_card_not_publishable"]
    assert decision["transcript_refs"]
    moments = [
        row for row in read_journal(tmp_path / "data")
        if row.get("kind") == "answer_needed_moment"
    ]
    assert len(moments) == 1
    query = moments[0]["payload"]["query"]
    assert "minimum" in query
    assert "parentheses" in query
    assert "valid" in query
    assert len(payload["transcript"]) == 2


def test_progressive_stt_restatement_collapses_visible_transcript(tmp_path: Path) -> None:
    app = create_app(make_settings(tmp_path))
    with TestClient(app) as client:
        client.post("/api/session/start", json={"consent_confirmed": True}).raise_for_status()

        post_turn(
            client,
            1,
            "A opening parentheses always has to come",
            kind="stabilized",
        )
        post_turn(
            client,
            2,
            "A opening parentheses always has to come before closing",
            kind="stabilized",
        )
        post_turn(
            client,
            3,
            "A opening parentheses always has to come before closing, right?",
            kind="final",
        )
        decisions = wait_for_publication_decisions(tmp_path / "data", 1)
        payload = client.get("/api/state").json()

    transcript_texts = [event["text"] for event in payload["transcript"]]
    assert transcript_texts == ["A opening parentheses always has to come before closing, right?"]
    assert payload["cards"] == []
    assert decisions[-1]["payload"]["status"] == "held"
    assert decisions[-1]["payload"]["reason_codes"] == ["insufficient_card_not_publishable"]
